func storageRows(v StorageView) []c.AccRow {
	return []c.AccRow{
		{Key: "backups", Title: "Backups", Summary: Count(len(v.Dests.Rows), "destination", "destinations"), Body: Backups(v.Dests)},
		{Key: "shares", Title: "Shares", Summary: Count(len(v.Shares.Rows), "share", "shares"), Body: Shares(v.Shares)},
		{Key: "registry", Title: "Registry", Summary: RegistrySummary(v.Registry), Body: Registry(v.Registry)},
	}
}

// RegistrySummary is the Registry row closed: the repository open, or how
// many there are.
func RegistrySummary(v RegistryView) string {
	switch {
	case v.Repo != "":
		return v.Repo
	case v.Host == "":
		return "No panel domain"
	case v.Err != "":
		return "Not answering"
	}
	return Count(len(v.Repos), "repository", "repositories")
}

